'use strict';const DB=window.CRPG_DATA,ASSETS=window.CRPG_ASSETS,{Runtime}=CRPGRuntime;let game=null,showArt=true,lastResult=null,selectedNPC=null;
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e},root=document.getElementById('root'),notice=document.getElementById('notice');
function say(s){notice.textContent=s||''}function button(text,fn,disabled=false,primary=false){const b=el('button',primary?'primary':'',text);b.disabled=disabled;b.onclick=fn;return b}function panel(title){const p=el('section','panel');if(title)p.append(el('h1','',title));return p}function actions(parent,opts){const a=el('div','actions');opts.forEach(x=>a.append(x));parent.append(a)}
function storeSave(){if(!game)return;try{localStorage.setItem('crpg-save:'+game.s.global.SAVE_ID,game.serialize());localStorage.setItem('crpg-latest',game.s.global.SAVE_ID)}catch{say('자동 저장을 사용할 수 없습니다. 시스템 메뉴에서 저장 파일을 내려받아 주세요.')}}
function act(type,params={}){try{lastResult=game.action(type,params);if(type==='NPC')selectedNPC=params.entity;storeSave();say('');render()}catch(e){say(e.message)}}
function art(parent,id){if(!showArt)return;const a=game.assetFor(id);if(a&&ASSETS[a[5]]){const img=el('img','art');img.src=ASSETS[a[5]];img.alt=id.startsWith('PROFILE_')?game.row('04_CHAR_DB',id)[2]:id;parent.append(img)}}
function fresh(){storeSave();game=null;render()}function begin(name,route){try{game=new Runtime(DB);game.newGame({name,route,seed:crypto.getRandomValues(new Uint32Array(1))[0]});lastResult=null;storeSave();say('');render()}catch(e){game=null;say(e.message)}}
function loadFile(){const f=el('input');f.type='file';f.accept='.json,application/json';f.onchange=async()=>{try{const r=new Runtime(DB,JSON.parse(await f.files[0].text()));game=r;storeSave();say('저장한 위치와 대기 선택지를 복원했습니다.');render()}catch(e){say('불러오지 못했습니다: '+e.message)}};f.click()}
function download(){const a=el('a');a.href=URL.createObjectURL(new Blob([game.serialize()],{type:'application/json'}));a.download='CRPG_'+game.s.global.SAVE_ID+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function setup(){const p=panel('새로운 여정');p.classList.add('welcome');p.prepend(el('div','eyebrow','MONDSTADT · CHAPTER 01'));p.append(el('p','muted','이름과 출발점을 정하세요. 새 여정마다 별도의 저장 파일이 만들어집니다.'));const name=el('input');name.placeholder='주인공 이름';name.maxLength=48;name.setAttribute('aria-label','주인공 이름');const route=el('select');route.setAttribute('aria-label','시작 루트');for(const [v,n]of [['ROUTE_ISEKAI','이세계인 · 낯선 초원에서'],['ROUTE_TRAVELER','여행자 · 페이몬과 숲길에서']]){let o=el('option','',n);o.value=v;route.append(o)}const row=el('div','row');row.append(name,route);p.append(row);actions(p,[button('여정 시작',()=>begin(name.value,route.value),false,true),button('백업 파일 가져오기',loadFile)]);try{const id=localStorage.getItem('crpg-latest');if(id){const s=JSON.parse(localStorage.getItem('crpg-save:'+id));p.append(button(s.global.PLAYER_NAME+' · 이어서 하기',()=>{try{game=new Runtime(DB,s);render()}catch(e){say(e.message)}}))}}catch{}root.append(p)}
function meter(parent,name,hp,max){parent.append(el('div','stat',name+'  '+hp+' / '+max));const m=el('div','meter'),i=el('i');i.style.width=Math.max(0,Math.min(100,hp/max*100))+'%';m.append(i);parent.append(m)}
function sidebar(g,v){const side=el('aside'),p=panel();p.append(el('div','eyebrow','DAY '+g.WORLD_DAY+' · '+g.WORLD_TIME));p.append(el('h2','',g.PLAYER_NAME));p.append(el('p','muted',v.map[2]));meter(p,'HP',g.PLAYER_HP_CURRENT,g.PLAYER_HP_MAX);p.append(el('div','stat','Lv.'+g.PLAYER_LEVEL_STATE+' · '+g.PLAYER_XP_STATE+' / '+g.PLAYER_XP_NEXT+' XP'));p.append(el('div','stat',g.MORA.toLocaleString()+' 모라'));const nav=el('nav');for(const [id,label]of [['STORY','이야기'],['LOCATION','장소·이동'],['SHOP','상점'],['INVENTORY','소지품·장비'],['CRAFT','제작·강화'],['QUEST','의뢰·관계'],['BOSS_INTRO','보스 도전'],['SYSTEM','저장·시스템']]){const b=button(label,()=>act('MENU',{screen:id}),!!game.s.runtime);if(g.SCREEN_MODE===id)b.classList.add('active');nav.append(b)}side.append(p,nav);return side}
function displayText(s){const q=game.quote(),v={PLAYER_NAME:game.s.global.PLAYER_NAME,STARTER_BOW_PRICE:q.stock[0].price,STARTER_COAT_PRICE:q.stock[1].price,STARTER_KIT_COST:q.total,STARTER_KIT_REMAINING_MORA:game.s.global.MORA-q.total};return String(s||'').replace(/\{(\w+)\}/g,(m,k)=>v[k]??m)}
function story(p,v){const n=v.node;p.append(el('div','eyebrow','STORY'));if(n){p.append(el('h1','',n[7]||'이야기'));art(p,n[6]);p.append(el('p','story',displayText(n[9])));actions(p,[button(n[5]==='COMBAT_GATE'?'전투 시작':'계속',()=>act('STORY_NEXT',{node:n[4]}),false,true)])}else if(v.choices.length){p.append(el('h1','','어떻게 할까?'));actions(p,v.choices.map(c=>button(displayText(c[10]),()=>act('STORY_CHOICE',{node:c[4]}))))}else{p.append(el('h1','','잠시 머무는 시간'));p.append(el('p','','현재 준비된 이야기 구간을 마쳤습니다. 주변을 살피고 다음 활동을 선택하세요.'));actions(p,[button('주변 둘러보기',()=>act('MENU',{screen:'LOCATION'}))])}}
function drawLocation(p,v){p.append(el('h1','',v.map[2]));p.append(el('span','badge',v.map[12]==='Y'?'안전한 거점':'야외 · 권장 Lv.'+v.map[6]+'–'+v.map[7]));p.append(el('h2','','이곳에서 만날 수 있는 사람과 시설'));const cards=el('div','grid');for(const npc of v.npcs){const c=el('div','card');c.append(el('h3','',npc.label),el('p','muted',npc.facility),button('찾아가기',()=>act('NPC',{entity:npc.entity_id})));cards.append(c)}if(!v.npcs.length)cards.append(el('p','muted','지금 이용할 수 있는 시설이 없습니다.'));p.append(cards,el('h2','','이동'));for(const {row:r,reason}of v.edges){p.append(button(r[9]+' · '+r[5]+'분',()=>act('MOVE',{edge:r[0]}),!!reason));if(reason)p.append(el('small','choice-note',reason))}actions(p,[button('이곳의 의뢰 확인',()=>act('MENU',{screen:'QUEST'})),button('1시간 기다리기',()=>act('WAIT',{minutes:60}))])}
function dialogue(p,v){const n=v.npcs.find(x=>x.entity_id===selectedNPC)||v.npcs.find(x=>x.entity_id===lastResult?.result?.entity);p.append(el('h1','',n?.label||'시설 방문'));art(p,n?.entity_id||'');p.append(el('p','',n?.facility||'현재 장소의 안내를 확인합니다.'));p.append(el('p','muted','필요한 일을 선택하세요.'));actions(p,[button('상점 보기',()=>act('MENU',{screen:'SHOP'})),button('의뢰·관계 보기',()=>act('MENU',{screen:'QUEST'})),button('작업 시설 이용',()=>act('MENU',{screen:'CRAFT'})),button('장소로 돌아가기',()=>act('MENU',{screen:'LOCATION'}))])}
function shop(p,v){p.append(el('h1','','상점'));const list=el('div','grid');for(const s of v.stocks){const r=s.row,c=el('div','card');c.append(el('h3','',r[4]),el('p','muted',game.row('18_MERCHANT_DB',r[1])[1]),el('p','',r[5]+' 모라 · 남은 재고 '+(s.remaining===Infinity?'상시':s.remaining)),button('1개 구매',()=>act('BUY',{stock:r[0],quantity:1}),!!s.reason));if(s.reason)c.append(el('small','choice-note',s.reason));list.append(c)}if(!v.stocks.length)list.append(el('p','muted','현재 장소·시간에 판매 중인 상품이 없습니다.'));p.append(list)}
function inventory(p){p.append(el('h1','','소지품·장비'));for(const item of game.s.inventory){const c=el('div','card'),r=game.row(item.equip?'16_EQUIP_DB':'14_ITEM_DB',item.equip||item.item);c.append(el('h3','',r[1]+(item.equip?' +'+item.enhance:' ×'+item.quantity)));if(item.equip){c.append(el('small','muted',item.equipped?'장착 중 · '+(item.owner==='PLAYER_CUSTOM'?game.s.global.PLAYER_NAME:game.row('07_CHAR_DB',item.owner)[1]):'미장착'));for(const member of game.s.party.filter(x=>x.active)){const owner=member.source;const label=owner==='PLAYER_CUSTOM'?'주인공':game.row('07_CHAR_DB',owner)[1];c.append(button(label+'에게 장착',()=>act('EQUIP',{slot:item.slot,owner}),item.equipped&&item.owner===owner));}}if(item.item?.startsWith('MAT_CHAR_EXP_'))c.append(button('주인공에게 1개 사용',()=>act('USE_ITEM',{item:item.item,quantity:1})));p.append(c)}if(!game.s.inventory.length)p.append(el('p','muted','아직 소지품이 없습니다.'));p.append(el('h2','','파티'));for(const slot of game.s.party.filter(x=>x.active))p.append(el('p','',slot.slot.replace('PARTY_','슬롯 ')+' · '+(slot.type==='PLAYER'?game.s.global.PLAYER_NAME:game.row('07_CHAR_DB',slot.source)[1])));}
function crafting(p){p.append(el('h1','','제작·강화'));for(const x of game.s.inventory.filter(x=>x.equip)){const c=el('div','card');c.append(el('h3','',game.row('16_EQUIP_DB',x.equip)[1]+' +'+x.enhance),button('다음 단계로 강화',()=>act('ENHANCE',{slot:x.slot})));const profile=JSON.parse(game.row('16_EQUIP_DB',x.equip)[32]||'{}'),cost=profile.costs?.[x.enhance+3];if(cost)c.append(el('p','muted',cost.mora+' 모라 · 철광 '+cost.items.ORE_IRON));p.append(c)}p.append(el('h2','','이곳에서 만들 수 있는 것'));let count=0;for(const r of game.rows('17_RECIPE_DB')){if(game.craftReason(r))continue;const c=el('div','card');c.append(el('h3','',game.row(r[2]==='EQUIP'?'16_EQUIP_DB':'14_ITEM_DB',r[3])[1]));c.append(el('p','muted',game.rows('48_RECIPE_INGREDIENT_DB').filter(x=>x[1]===r[0]).map(x=>game.row('14_ITEM_DB',x[3])[1]+' ×'+x[4]).join(' · ')),button('제작',()=>act('CRAFT',{recipe:r[0]})));p.append(c);count++;}if(!count)p.append(el('p','muted','현재 시설과 해금 조건에 맞는 제작법이 없습니다.'))}
function quests(p,v){p.append(el('h1','','의뢰·관계'));for(const q of v.quests){const def=JSON.parse(q.row[10]);if(def.map_id!==game.s.global.CURRENT_MAP_ID)continue;const c=el('div','card');c.append(el('h3','',q.row[1]),el('p','',q.state?.claimed?def.revisit:def.text));if(q.reason)c.append(el('small','choice-note',q.reason));else if(q.state?.node==='READY_TO_CLAIM'){const reward=JSON.parse(q.row[11]);if(reward.equipment_choice)for(const id of reward.equipment_choice)c.append(button(game.row('16_EQUIP_DB',id)[1]+' 수령',()=>act('CLAIM_QUEST',{quest:q.row[0],equipment:id})));else c.append(button('보상 수령',()=>act('CLAIM_QUEST',{quest:q.row[0]}),false,true));}else for(const choice of def.choices)c.append(button(choice.label,()=>act('QUEST_CHOICE',{quest:q.row[0],choice:choice.id})));p.append(c)}p.append(el('h2','','실제로 만난 인물'));for(const [pid,r]of Object.entries(game.s.relations)){const def=game.row('04_CHAR_DB',pid),c=el('div','card');c.append(el('h3','',def[2]),el('p','muted','관계 변화 '+r.heart+' · '+(r.companion==='TEMPORARY'?'일시 동행':r.companion==='DEPARTED'?'동행 종료':r.companion==='JOINED'?'합류 수락':'만남 기록')),el('p','',r.unlocked.length?'해금한 정보: 현장 활동 조언':'아직 추가로 해금한 정보가 없습니다.'));if(game.s.global.CURRENT_MAP_ID==='MAP_MOND_CITY'){const ev=game.rows('51_EVENT_DB').find(e=>e[6]==='PERSONAL_EVENT'&&JSON.parse(e[13]).profile_id===pid);if(ev){const ep=JSON.parse(ev[13]);for(const ch of ep.choices)c.append(button(ch.label,()=>act('PERSONAL',{event:ev[0],choice:ch.id}),r.events[ep.event_id]==='COMPLETE'));}}if(['TEMPORARY','JOINED'].includes(r.companion)&&!game.s.party.some(p=>p.active&&p.source===def[1]))c.append(button('빈 슬롯에 편성',()=>act('PARTY',{char:def[1],slot:game.s.party.findIndex(x=>!x.active)+1})));p.append(c)}}
function combat(p){const b=game.s.runtime;p.append(el('div','eyebrow','ROUND '+b.round));p.append(el('h1','',game.row('33_ENCOUNTER_GROUP_DB',b.group)[1]));const grid=el('div','grid');for(const a of b.actors){const c=el('div','card');c.append(el('h3','',a.name+(a.side==='ENEMY'?' · 적':' · 아군')));meter(c,'HP',a.hp,a.maxHp);if(showArt&&a.side==='ENEMY'){const fn='enemy_'+game.row('09_MONSTER_DB',a.source)[15]+'.png';if(ASSETS[fn]){const img=el('img','art');img.src=ASSETS[fn];img.alt=a.name;c.append(img);}}if(a.side==='ENEMY'&&a.hp>0)c.append(button('공격 대상으로 선택',()=>act('COMBAT',{card:'PLAYER_BASIC_ATTACK',target:a.id})));grid.append(c)}p.append(grid);if(b.terrain!==null)p.append(el('p','muted','남은 지형 '+b.terrain+' / 4 · 8라운드 종료 전 격파'));p.append(button('방어하고 다음 행동까지 버틴다',()=>act('COMBAT',{card:'PLAYER_BASIC_GUARD'})));const l=el('div','log');for(const e of b.log.slice(-8))l.append(el('p','',e.actor+(e.miss?'의 공격이 빗나갔다.':e.damage?' → '+e.target+' · 피해 '+e.damage:e.guard?' 방어':e.card?' · '+game.row('08_SKILL_CARD_DB',e.card)[3]:'')));p.append(l)}
function reward(p){p.append(el('h1','','결과'));const b=JSON.parse(game.s.global.LAST_BATTLE_RESULT_JSON||'{}');if(b.id){p.append(el('h2','',b.victory?'전투 승리':'거점으로 복귀'),el('p','',b.rounds+'라운드 · 경험치 '+b.xp));for(const [id,n]of Object.entries(b.loot||{}))p.append(el('p','',game.row('14_ITEM_DB',id)[1]+' ×'+n));}if(lastResult?.type==='CLAIM_QUEST')p.append(el('p','','의뢰 보상을 수령했습니다. 소지품과 모라에 반영했습니다.'));actions(p,[button('이곳의 의뢰·보상 확인',()=>act('MENU',{screen:'QUEST'}),false,true),button('소지품 확인',()=>act('MENU',{screen:'INVENTORY'})),button('이야기로 돌아가기',()=>act('MENU',{screen:'STORY'})),button('장소로 돌아가기',()=>act('MENU',{screen:'LOCATION'}))])}
function boss(p){p.append(el('h1','','보스 도전'));const routes=game.rows('35_BOSS_ROUTE_DB').filter(r=>r[2]===game.s.global.CURRENT_MAP_ID);if(!routes.length)p.append(el('p','muted','이곳에는 보스 도전 입구가 없습니다.'));for(const r of routes){const c=el('div','card');c.append(el('h3','',r[1]),el('p','',r[15]));if(r[8]==='Y')c.append(button('보스 직행',()=>act('BOSS_ROUTE',{route:r[0],entry:'DIRECT'})));c.append(button('전초전부터 시작',()=>act('BOSS_ROUTE',{route:r[0],entry:'GAUNTLET'})));p.append(c)}}
function system(p){p.append(el('h1','','저장·시스템'));p.append(el('p','','현재 위치, 선택 대기, 파티와 보상 기록을 함께 저장합니다. 전투 중에는 마지막으로 완료된 행동 뒤부터 이어집니다.'));actions(p,[button('저장 백업 파일 내보내기',download,false,true),button('백업 파일 가져오기',loadFile),button('다른 새 여정 만들기',fresh)]);const label=el('label','row'),check=el('input');check.type='checkbox';check.checked=showArt;check.onchange=()=>{showArt=check.checked;render()};label.append(check,el('span','','보유한 장면 일러스트 표시'));p.append(label);const d=el('details');d.append(el('summary','','실행 범위 확인'),el('p','muted','초반 흐름과 정해진 전투 처리기를 확인한 실행본입니다. 아직 연결하지 않은 전용 카드·강화·조건은 실행 전에 안내합니다. 시트의 최신 변경은 이 파일에 자동 동기화되지 않습니다.'));p.append(d)}
function render(){root.replaceChildren();if(!game){setup();return}const g=game.s.global,v=game.view(),main=el('main'),body=el('div'),p=panel();main.append(sidebar(g,v),body);body.append(p);root.append(main);if(game.s.runtime){combat(p);return}switch(g.SCREEN_MODE){case'STORY':story(p,v);break;case'DIALOGUE':dialogue(p,v);break;case'SHOP':shop(p,v);break;case'INVENTORY':inventory(p);break;case'CRAFT':crafting(p);break;case'QUEST':quests(p,v);break;case'SYSTEM':system(p);break;case'REWARD':reward(p);break;case'BOSS_INTRO':boss(p);break;default:drawLocation(p,v)}}
window.CRPG_APP={get game(){return game},begin,act,render,loadState(s){game=new Runtime(DB,s);render()}};
